{
  "plans": [
    {
      "id": "replace-indefinite-begin-with-0s",
      "description": "All three animateTransform elements use begin=\"indefinite\", so they never start automatically. Changing begin to \"0s\" starts each animation immediately while preserving duration, rotation targets, and geometry.",
      "goal": "Use workspace.read_text to confirm the three begin=\"indefinite\" occurrences. Use workspace.preview_text_patch to replace begin=\"indefinite\" with begin=\"0s\" on the back-spin, front-spin, and pedal-spin animateTransform elements. Use workspace.apply_text_patch to apply the exact-text replacements. Run pelican.verify to confirm the animations start and no geometry or timing changed."
    },
    {
      "id": "add-parent-begin-trigger",
      "description": "Keep the animateTransform begin=\"indefinite\" values but add a parent SVG timeline trigger so the animations are started by a separate begin event. This preserves the existing animation elements and their indefinite state while providing an explicit start condition.",
      "goal": "Use workspace.read_text to inspect the root SVG and the three animateTransform elements. Use workspace.preview_text_patch to add a begin event source, such as begin=\"0s\" on a harmless existing or new non-visual element, and change each animateTransform begin from \"indefinite\" to reference that event if needed. Use workspace.apply_text_patch to apply the exact-text patch. Run pelican.verify to confirm all three animations start and that no geometry, duration, or rotation targets changed."
    },
    {
      "id": "convert-to-css-animation-fallback",
      "description": "If SVG begin timing remains unreliable, replace only the three animateTransform start behavior with CSS animations on the same wheel and pedal groups. Keep the existing geometry, durations, and rotation targets by using equivalent CSS keyframes and transform-origin values.",
      "goal": "Use workspace.read_text to identify the three animateTransform elements and their parent groups. Use workspace.preview_text_patch to add a style block with CSS keyframes for back-spin, front-spin, and pedal-spin, and apply those animations to #wheel-back, #wheel-front, and #pedal while removing or neutralizing the animateTransform elements. Use workspace.apply_text_patch to apply the exact-text patch. Run pelican.verify to confirm the three rotations animate for 1.6s around the correct centers and that all original SVG geometry remains intact."
    }
  ]
}
